    super._showElement({ modal, preventBodyScroll })
    // Focus the close button after showing
    const closeButton = this._element.querySelector('[data-bs-dismiss="drawer"]')
    if (closeButton instanceof HTMLElement) {
      closeButton.focus()
    }
  }

  // Private

  protected _initResizeObserver(): void {"
